if(!defined('WP_CLI')||!WP_CLI)throw new RuntimeException('CLI only');
$mode=getenv('IPCC_MODE')?:'verify';$path=getenv('IPCC_BACKUP');
function ipce_hashes($orders=false){$a=[];foreach($orders?wc_get_orders(['limit'=>-1]):wc_get_products(['limit'=>-1,'status'=>['publish','draft','private','pending']]) as $p)$a[$p->get_id()]=hash('sha256',wp_json_encode($p->get_data()));return $a;}
function ipce_spec($groups){$a=[];foreach($groups as $g)if(ipl_credit($g)){if(array_map('intval',array_keys($g['offers']))!==range(50,500,25))throw new RuntimeException('Credit amounts changed');foreach($g['offers'] as $face=>$o)$a[$o['id']]=[$g['key'],(int)$face];}if(count($a)!==38)throw new RuntimeException('Expected38 credit offers');return $a;}
function ipce_options(){ $a=[];foreach(['instapass_pkr_rate','instapass_rate_history','instapass_promotion','instapass_promotion_three','instapass_promotion_four','woocommerce_instapass_transfer_settings','woocommerce_instapass_crypto_settings','woocommerce_instapass_binance_settings','woocommerce_instapass_easypaisa_settings','woocommerce_instapass_nayapay_settings'] as $k)$a[$k]=get_option($k);return $a;}
function ipce_verify(){ $checks=0;$spec=ipce_spec(ipl_groups());foreach(ipl_groups() as $g)foreach($g['offers'] as $o){if(empty($o['ready']))throw new RuntimeException('Offer still held');$checks++;}foreach($spec as $id=>[$family,$face]){$p=wc_get_product($id);if((float)$p->get_regular_price('edit')!==$face*.4||$p->get_sale_price('edit')!==''||$p->get_date_on_sale_from('edit')||$p->get_date_on_sale_to('edit')||$p->get_meta('_instapass_pkr_regular_price')!=='')throw new RuntimeException('Base price mismatch');$checks++;foreach(['USD','GBP','EUR','PKR'] as $c){$v=instapass_cc_amount($p->get_price('edit'),$p,'price',$c);if(abs((float)$v-$face*.4*($c==='PKR'?280:1))>.001)throw new RuntimeException('Currency base mismatch');$checks++;}if(!ip_offer_coupon_allowed($p))throw new RuntimeException('Coupon eligibility missing');$checks++;if($family==='claude-credits'&&($p->get_meta('_instapass_credit_expiry')!=='batch'||$p->get_meta('_instapass_validity')!=='Credit batch expiry'))throw new RuntimeException('Claude batch metadata');if($family==='chatgpt-credits'&&($p->get_meta('_instapass_credit_expiry')!=='monthly'||$p->get_meta('_instapass_validity')!=='1 month'))throw new RuntimeException('ChatGPT month metadata');$checks++;}if(ip_ce_config()!==ip_ce_defaults())throw new RuntimeException('Unexpected initial policy');$checks++;return ['result'=>'pass','checks'=>$checks,'families'=>8,'approved_offers'=>52,'credit_options'=>38,'policy'=>ip_ce_config(),'current_cycle'=>ip_ce_state(),'no_order_or_email_sent'=>true];}
if($mode==='verify'){echo wp_json_encode(ipce_verify(),JSON_PRETTY_PRINT);return;}
if(!$path||!str_starts_with($path,'/opt/instapass/recovery/'))throw new RuntimeException('Protected backup required');add_filter('pre_wp_mail','__return_true',999);if(class_exists('Instapass_Notifications'))remove_action('woocommerce_update_product',['Instapass_Notifications','restocked']);
if($mode==='rollback'){$b=json_decode(file_get_contents($path),true,512,JSON_THROW_ON_ERROR);foreach($b['targets'] as $id=>$v){$p=wc_get_product($id);foreach(['regular_price','sale_price','price','description','short_description'] as $k)$p->{'set_'.$k}($v[$k]);$p->set_date_on_sale_from($v['from']);$p->set_date_on_sale_to($v['to']);foreach($v['meta'] as $k=>$x)if($x['exists'])$p->update_meta_data($k,$x['value']);else $p->delete_meta_data($k);$p->save();wc_delete_product_transients($id);}update_option('instapass_launch_groups',$b['groups'],false);if($b['cycle']===false)delete_option('instapass_claude_credit_cycle');else update_option('instapass_claude_credit_cycle',$b['cycle'],false);echo 'Scoped credit cycle rollback complete';return;}
$groups=ipl_groups();$ready=0;foreach($groups as $g)foreach($g['offers'] as $o)if(!empty($o['ready']))$ready++;if($mode!=='apply'||file_exists($path)||count($groups)!==8||$ready!==14||get_option('instapass_claude_credit_cycle',false)!==false||instapass_control_rate()!=='280.00')throw new RuntimeException('State changed; re-review');
$spec=ipce_spec($groups);$metas=['_instapass_pkr_regular_price','_instapass_pkr_sale_price','_instapass_gbp_regular_price','_instapass_gbp_sale_price','_instapass_eur_regular_price','_instapass_eur_sale_price','_ip_offer_sale_from','_ip_offer_sale_to','_ip_offer_coupons','_instapass_credit_expiry','_instapass_validity'];$b=['groups'=>$groups,'cycle'=>false,'products'=>ipce_hashes(),'orders'=>ipce_hashes(true),'options'=>ipce_options(),'targets'=>[]];
foreach($spec as $id=>$s){$p=wc_get_product($id);$v=[];foreach(['regular_price','sale_price','price','description','short_description'] as $k)$v[$k]=$p->{'get_'.$k}('edit');$v['from']=$p->get_date_on_sale_from('edit')?->getTimestamp();$v['to']=$p->get_date_on_sale_to('edit')?->getTimestamp();$v['stock']=[$p->get_stock_status('edit'),$p->get_manage_stock('edit'),$p->get_stock_quantity('edit')];foreach($metas as $k)$v['meta'][$k]=['exists'=>$p->meta_exists($k),'value'=>$p->get_meta($k,true,'edit')];$b['targets'][$id]=$v;}file_put_contents($path,wp_json_encode($b,JSON_PRETTY_PRINT));chmod($path,0600);
foreach($spec as $id=>[$family,$face]){$p=wc_get_product($id);$base=number_format($face*.4,2,'.','');$p->set_regular_price($base);$p->set_sale_price('');$p->set_price($base);$p->set_date_on_sale_from(null);$p->set_date_on_sale_to(null);foreach(['gbp','eur'] as $c){$p->update_meta_data('_instapass_'.$c.'_regular_price',$base);$p->delete_meta_data('_instapass_'.$c.'_sale_price');}$p->delete_meta_data('_instapass_pkr_regular_price');$p->delete_meta_data('_instapass_pkr_sale_price');$p->update_meta_data('_ip_offer_sale_from',0);$p->update_meta_data('_ip_offer_sale_to',0);$p->update_meta_data('_ip_offer_coupons','yes');$claude=$family==='claude-credits';$p->update_meta_data('_instapass_credit_expiry',$claude?'batch':'monthly');$p->update_meta_data('_instapass_validity',$claude?'Credit batch expiry':'1 month');$desc='<p>Choose between $50 and $500 in credit balance, in $25 increments. The credit balance is separate from the one-time purchase price.</p><p>'.($claude?'Claude credits share a monthly batch expiry. The exact expiry and current rate are shown before purchase. Buying later does not extend the expiry.':'ChatGPT credits provide one full month and cost40% of the selected credit balance before any qualifying bundle coupon.').'</p>';$p->set_description($desc);$p->set_short_description($claude?'<p>Credit balance with a shared monthly expiry; price varies by time remaining.</p>':'<p>Choose your credit balance. Valid for one full month.</p>');$p->save();wc_delete_product_transients($id);}
foreach($groups as &$g)if(ipl_credit($g)){$g['caption']=$g['key']==='claude-credits'?'Choose your credit balance. Price falls as the batch expiry approaches.':'Choose your credit balance. Valid for one full month.';foreach($g['offers'] as &$o)$o['ready']=true;unset($o);}unset($g);add_option('instapass_claude_credit_cycle',ip_ce_defaults(),'','no');update_option('instapass_launch_groups',$groups,false);
$now=ipce_hashes();foreach($b['products'] as $id=>$hash)if(!isset($spec[$id])&&($now[$id]??null)!==$hash)throw new RuntimeException('Other product changed');$now=ipce_hashes(true);foreach($b['orders'] as $id=>$hash)if(($now[$id]??null)!==$hash)throw new RuntimeException('Historical order changed');if(ipce_options()!==$b['options'])throw new RuntimeException('Other options changed');foreach($b['targets'] as $id=>$v){$p=wc_get_product($id);if([$p->get_stock_status('edit'),$p->get_manage_stock('edit'),$p->get_stock_quantity('edit')]!==$v['stock'])throw new RuntimeException('Stock changed');}$result=ipce_verify();$result['other_products_orders_stock_options_preserved']=true;echo wp_json_encode($result,JSON_PRETTY_PRINT);
